package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;
final class MeetingActionsDialog {
 static void show(MainActivity owner,String id){new Thread(()->{try{JSONObject source=MeetingActions.preview(owner,id);owner.runOnUiThread(()->{if(owner.isDestroyed())return;LinearLayout box=new LinearLayout(owner);box.setOrientation(1);box.setPadding(20,12,20,12);TextView note=new TextView(owner);note.setText("要約からの候補です。日時・担当・内容を確認して保存してください。予定は登録しません。");box.addView(note);JSONArray candidates=source.optJSONArray("items");if(candidates.length()==0){TextView empty=new TextView(owner);empty.setText("保留候補はありません");box.addView(empty);}for(int i=0;i<candidates.length();i++){JSONObject candidate=candidates.optJSONObject(i);EditText text=new EditText(owner);text.setText(candidate.optString("text"));text.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(800)});box.addView(text);Button save=new Button(owner);save.setText("確認した内容を保留保存");save.setOnClickListener(v->{String value=text.getText().toString();new AlertDialog.Builder(owner).setMessage(value+"\nこの内容を保留保存します。予定は登録しません。").setPositiveButton("保存",(d,w)->{save.setEnabled(false);new Thread(()->{try{MeetingActions.save(owner,id,source.getString("sourceHash"),candidate.getInt("index"),value);owner.runOnUiThread(()->{save.setText("保留保存済み");text.setEnabled(false);});}catch(Exception e){owner.runOnUiThread(()->{save.setEnabled(true);note.setText(e.getMessage());});}},"SaveMeetingCandidate").start();}).setNegativeButton("戻る",null).show();});box.addView(save);}ScrollView scroll=new ScrollView(owner);scroll.addView(box);new AlertDialog.Builder(owner).setTitle("会議要約から保留候補を確認").setView(scroll).setPositiveButton("閉じる",null).show();});}catch(Exception e){owner.runOnUiThread(()->Toast.makeText(owner,e.getMessage(),Toast.LENGTH_LONG).show());}},"MeetingCandidates").start();}
 private MeetingActionsDialog(){}
}
